const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let registryPromise;
const colors={O:'#ce6374',Zn:'#6c96ba',In:'#91a3c6',P:'#d4a457',Cs:'#9983bd',Pb:'#6b91aa',Br:'#b78654',Co:'#789baa',Fe:'#c48c59',Ir:'#7993a7',X:'#9575b0'};
export async function mountCrystalReferences(host,r){
 if(!host)return;host.replaceChildren();registryPromise??=fetch(new URL('assets/crystal-references/registry.json',import.meta.url),{cache:'no-store'}).then(r=>r.json());const data=await registryPromise;const entries=data.entries.filter(x=>(x.record_ids||[]).includes(r.record_id));if(!entries.length)return;
 host.append(el('h3','Reference crystal structures'),el('p','Independent bulk references for comparison. The unit cell and extended lattice are illustrative references, not atom-by-atom reconstructions of the synthesized nanocrystal.','guide-notice'));const grid=el('div',undefined,'crystal-reference-grid');host.append(grid);
 for(const ref of entries){const card=el('article',undefined,'crystal-reference-card'),view=el('div',undefined,'crystal-reference-view');view.tabIndex=0;view.setAttribute('aria-label',ref.name+' interactive crystal viewer');card.append(el('h4',ref.name),view,el('small',ref.scope||ref.description));const downloads=el('div',undefined,'protocol-controls');for(const [label,url] of [['Download reference CIF ↓',new URL('assets/crystal-references/'+ref.cifPath,import.meta.url)],['Structure source ↗',ref.sourceUrl]]){const a=el('a',label);a.href=url;downloads.append(a);}card.append(downloads);grid.append(card);if(!window.$3Dmol)continue;
 const model=await(await fetch(new URL('assets/crystal-references/'+ref.modelPath+'?sha='+ref.modelSha256,import.meta.url))).json(),v=model.cellVectors;const viewer=$3Dmol.createViewer(view,{backgroundColor:'#f5f9fc'});let extent=1;
 const point=(i,j,k)=>({x:i*v[0][0]+j*v[1][0]+k*v[2][0],y:i*v[0][1]+j*v[1][1]+k*v[2][1],z:i*v[0][2]+j*v[1][2]+k*v[2][2]});
 function draw(n){extent=n;viewer.clear();let aa=[];for(let i=0;i<n;i++)for(let j=0;j<n;j++)for(let k=0;k<n;k++){const off=point(i,j,k);for(const a of model.atoms)aa.push({serial:aa.length,elem:a.element??a.elem,x:a.x+off.x,y:a.y+off.y,z:a.z+off.z,properties:a.properties});}viewer.addModel().addAtoms(aa);for(const species of new Set(aa.map(a=>a.elem)))viewer.setStyle({elem:species},{sphere:{radius:species==='X'?.32:species==='O'?.26:.38,color:colors[species]||'#7894a7'}});
 for(let axis=0;axis<3;axis++)for(const b of [0,n])for(const c of [0,n]){const start=[b,c];start.splice(axis,0,0);const end=[...start];end[axis]=n;viewer.addLine({start:point(...start),end:point(...end),color:'#89a1b2',linewidth:1});}
 viewer.zoomTo();viewer.rotate(15,'y');viewer.rotate(-12,'x');viewer.render();}
 draw(1);const controls=el('div',undefined,'protocol-controls');for(const [label,n] of [['Unit cell',1],['2 × 2 × 2 lattice',2]]){const b=el('button',label);b.type='button';b.onclick=()=>draw(n);controls.append(b);}card.insertBefore(controls,view);card.append(el('small',`${ref.spaceGroup} · a=${model.cell.a}, b=${model.cell.b}, c=${model.cell.c} Å; α=${model.cell.alpha}°, β=${model.cell.beta}°, γ=${model.cell.gamma}°. Drag to rotate; scroll to zoom.`));
 if(ref.mixedOccupancy){const sites=[...new Set(model.atoms.filter(a=>a.mixed_site).map(a=>(a.components||[]).map(c=>c.element+' '+c.occupancy).join(' / ')))];card.append(el('p','Purple markers are statistically mixed Co/Fe sites, not an element X or an ordered assignment. Site occupancies: '+sites.join('; ')+'.','guide-notice'));}
 view.onkeydown=e=>{const turns={ArrowLeft:[-12,'y'],ArrowRight:[12,'y'],ArrowUp:[-12,'x'],ArrowDown:[12,'x']}[e.key];if(turns)viewer.rotate(...turns);else if(e.key==='Home')draw(extent);else if(['+','='].includes(e.key))viewer.zoom(1.15);else if(e.key==='-')viewer.zoom(1/1.15);else return;e.preventDefault();viewer.render();};const observer=new ResizeObserver(()=>{if(view.isConnected){viewer.resize();viewer.render();}else{viewer.clear();observer.disconnect();}});observer.observe(view);
 }
}
